tree=ET.parse(sm); root=tree.getroot()
def ensure_url(loc, priority='0.7', image=None, title=None, caption=None):
    node=None
    for u in root.findall(ns+'url'):
        l=u.find(ns+'loc')
        if l is not None and l.text==loc: node=u; break
    if node is None:
        node=ET.SubElement(root, ns+'url'); ET.SubElement(node, ns+'loc').text=loc
    lm=node.find(ns+'lastmod')
    if lm is None: lm=ET.SubElement(node, ns+'lastmod')
    lm.text=DATE
    cf=node.find(ns+'changefreq')
    if cf is None: cf=ET.SubElement(node, ns+'changefreq')
    cf.text='weekly'
    pr=node.find(ns+'priority')
    if pr is None: pr=ET.SubElement(node, ns+'priority')
    pr.text=priority
    for im in list(node.findall(ins+'image')): node.remove(im)
    if image:
        im=ET.SubElement(node, ins+'image')
        ET.SubElement(im, ins+'loc').text=image
        ET.SubElement(im, ins+'title').text=title
        ET.SubElement(im, ins+'caption').text=caption
ensure_url(BASE+'/blog/','0.9')
for a in articles:
    ensure_url(f'{BASE}/blog/{a["slug"]}/','0.7',BASE+a['image'],a['title'],a['image_alt'])
